map.set(Repair, []);
map.set(Staff, []);
map.set(Device, []);
map.set(ApprovalHistory, []);
const getRepository = <T,>(clazz: new (...args: any[]) => T) => {
  return map.get(clazz) as T[];
};
export { Repair, Staff, Device, ApprovalHistory, getRepository };

