class RepairService_AutoGenerated {
  /*find the repair and  staff with provided id, sid,
   *if the repair raised staff is the staff and the role is 0, and the repair process is 7
   *the repair score is provided score and if the score greater or equal to 3 then close the repair,
   *or the repair shouldn't be closed and the repair descirption should be the des and the repair process is set to 0, and save the repair*/
  feedback(id: number, sid: number, score: number, des: string): boolean {
    /*Definition Start*/
    let repair: Repair = l({
      logic: () =>
        getRepository(Repair).find(
          (o: any) =>
            l({
              logic: () => o.Id === id,
              description: "o.Id=id",
            }).build().pass,
        ),
      description: "Repair.allInstance()->any(o|o.Id=id)",
    }).build().pass;
    let staff: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (o: any) =>
            l({
              logic: () => o.Id === sid,
              description: "o.Id=sid",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(o|o.Id=sid)",
    }).build().pass;
    let isStaffClosed: boolean = l({
      logic: () => repair.RaiseStaff === staff,
      description: "repair.RaiseStaff=staff",
    })
      .and({
        logic: () => staff.Role === 0,
        description: "staff.Role=0",
      })
      .and({
        logic: () => repair.Process === 7,
        description: "repair.Process=7",
      })
      .build().pass;
    let isScoreValid: boolean = l({
      logic: () => score >= 3,
      description: "score>=3",
    }).build().pass;
    let isClosed: boolean = l({
      logic: () => isStaffClosed,
      description: "isStaffClosed",
    })
      .and({
        logic: () => score >= 3,
        description: "score>=3",
      })
      .build().pass;
    let isNewRepair: boolean = l({
      logic: () => (repair = new Repair()),
      description: "repair.oclIsNew()",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(repair),
        description: "repair.oclIsUndefined()",
      })
        .and({
          logic: () => StandardOPs.oclIsUndefined(staff),
          description: "staff.oclIsUndefined()",
        })
        .and({
          logic: () => repair.Id === id,
          description: "repair.Id=id",
        })
        .and({
          logic: () => staff.Id === sid,
          description: "staff.Id=sid",
        })
        .and({
          logic: () =>
            l({
              logic: () => isStaffClosed,
              description: "isStaffClosed",
            }).or({
              logic: () => isScoreValid,
              description: "isScoreValid",
            }),
          description: "(isStaffClosedorisScoreValid)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let repairInstance: Repair;
    return l({
      execute: () => (repairInstance = new Repair()),
      description: "repairInstance.oclIsNew()",
    })
      .and({
        execute: () => (repair.Close = isClosed),
        description: "repair.Close=isClosed",
      })
      .and({
        execute: () => (repair.Description = des),
        description: "repair.Description=des",
      })
      .and({
        execute: () => (repair.Process = 0),
        description: "repair.Process=0",
      })
      .and({
        execute: () => isNewRepair,
        description: "result=isNewRepair",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { RepairService_AutoGenerated };

